const history = Object.values(
  $json.history_data
)[0];

let image = null;

for (const output of Object.values(history.outputs)) {
  if (output.images && output.images.length > 0) {
    image = output.images[0];
    break;
  }
}

if (!image) {
  throw new Error("No generated image found");
}

return [
  {
    json: {
      image_path: `C:/AI/ComfyUI_windows_portable_nvidia_cu126/ComfyUI_windows_portable/ComfyUI/output/${image.filename}`,
      filename: image.filename,
      subfolder: image.subfolder,
      type: image.type
    }
  }
];

const keys = Object.keys($json);

return [
  {
    json: {
      has_history: keys.length > 0,
      history_data: $json
    }
  }
];
